function findUser(id: string): { name: string } | null {
  return db.has(id) ? { name: db.get(id)! } : null;
}

function greet(id: string): string {
  const user = findUser(id);
  if (user === null) return 'Not found';
  return `Hello, ${user.name}`;
}

